def choose_move(observation):
    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def get_pos(obj, keys, default=None):
        if obj is None:
            return default
        for k in keys:
            try:
                v = obj.get(k)
            except AttributeError:
                v = None
            if v is not None:
                return v
        return default

    def first_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        return None

    def dist2(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def best_by_distance(items, p, reverse=False):
        best = None
        best_d = None
        for it in items or []:
            pt = first_pair(it)
            if pt is None:
                continue
            d = dist2(pt, p)
            if best is None or (d > best_d if reverse else d < best_d):
                best = pt
                best_d = d
        return best

    env = observation.get("environment_name", "") if hasattr(observation, "get") else ""
    sx_sy = get_pos(observation, ("self_position", "self_pos", "position"), [0, 0])
    ox_oy = get_pos(observation, ("opponent_position", "enemy_position", "opponent_pos"), None)
    sx, sy = sx_sy[0], sx_sy[1]
    ox, oy = (ox_oy[0], ox_oy[1]) if ox_oy is not None else (None, None)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") if hasattr(observation, "get") else "pursuer"
        if role == "pursuer" and ox_oy is not None:
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        gw = observation.get("grid_width", 0) if hasattr(observation, "get") else 0
        gh = observation.get("grid_height", 0) if hasattr(observation, "get") else 0
        corners = [[0, 0], [0, max(0, gh - 1)], [max(0, gw - 1), 0], [max(0, gw - 1), max(0, gh - 1)]]
        if ox_oy is not None:
            target = best_by_distance(corners, [ox, oy], reverse=True) or corners[0]
        else:
            target = corners[0]
        return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier_cells", "targets"):
            val = observation.get(key) if hasattr(observation, "get") else None
            if val:
                targets = val
                break
        pt = best_by_distance(targets, [sx, sy], reverse=False)
        if pt is not None:
            return [clamp_step(sx, pt[0]), clamp_step(sy, pt[1])]
        if ox_oy is not None:
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        return [0, 0]

    resources = []
    for key in ("resources", "resource_positions", "items", "coins"):
        val = observation.get(key) if hasattr(observation, "get") else None
        if val:
            resources = val
            break

    if resources:
        # Prefer closer resources; if a carrying/status field exists, bias toward the nearest.
        pt = best_by_distance(resources, [sx, sy], reverse=False)
        if pt is not None:
            return [clamp_step(sx, pt[0]), clamp_step(sy, pt[1])]

    # Fallbacks: move toward opponent if seen, else stay.
    if ox_oy is not None:
        return [clamp_step(sx, ox), clamp_step(sy, oy)]
    return [0, 0]

